package com.casaraodocampo.carteira;

import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.net.Uri;import android.provider.Settings;import android.view.*;import android.widget.*;import java.io.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
 int green=Color.rgb(32,61,49), gold=Color.rgb(212,176,106), cream=Color.rgb(247,240,228); DB db; LinearLayout body;
 public void onCreate(Bundle b){super.onCreate(b);db=new DB(this); login();}
 TextView tv(String s,int sp){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(green);v.setPadding(18,12,18,12);return v;}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
 Button bt(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(13);b.setAllCaps(true);b.setGravity(Gravity.CENTER);b.setBackgroundColor(green);b.setMinHeight(dp(52));b.setPadding(dp(6),dp(8),dp(6),dp(8));return b;}
 void login(){
  ScrollView sc=new ScrollView(this); sc.setFillViewport(true); sc.setBackgroundColor(cream);
  LinearLayout l=new LinearLayout(this); l.setOrientation(LinearLayout.VERTICAL); l.setGravity(Gravity.CENTER_HORIZONTAL); l.setPadding(dp(20),dp(24),dp(20),dp(36));
  ImageView im=new ImageView(this); im.setImageResource(R.drawable.casarao); im.setScaleType(ImageView.ScaleType.CENTER_INSIDE); im.setAdjustViewBounds(true);
  l.addView(im,new LinearLayout.LayoutParams(-1,dp(340)));
  TextView h=tv("CARTEIRA DE CLIENTES",25); h.setGravity(Gravity.CENTER); h.setPadding(0,dp(18),0,dp(12)); l.addView(h);
  EditText u=new EditText(this);u.setHint("USUÁRIO");u.setText("admin");u.setSingleLine(true);l.addView(u,new LinearLayout.LayoutParams(-1,dp(58)));
  EditText pw=new EditText(this);pw.setHint("SENHA");pw.setInputType(129);pw.setText("1234");pw.setSingleLine(true);l.addView(pw,new LinearLayout.LayoutParams(-1,dp(58)));
  Button e=bt("ENTRAR"); LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,dp(58));ep.setMargins(0,dp(16),0,dp(24));l.addView(e,ep);
  e.setOnClickListener(v->{if(u.getText().toString().equals("admin")&&pw.getText().toString().equals("1234"))dash();else Toast.makeText(this,"LOGIN INCORRETO",Toast.LENGTH_SHORT).show();});
  sc.addView(l,new ScrollView.LayoutParams(-1,-2));setContentView(sc);
 }
 void shell(String title){
  ScrollView sc=new ScrollView(this);sc.setFillViewport(true);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setBackgroundColor(cream);body.setPadding(dp(12),dp(18),dp(12),dp(36));
  TextView brand=tv("CASARÃO DO CAMPO",22);brand.setTextColor(green);brand.setAllCaps(true);body.addView(brand);
  TextView h=tv(title.toUpperCase(),20);h.setTextColor(green);h.setPadding(dp(18),0,dp(18),dp(10));body.addView(h);
  LinearLayout nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);nav.setBackgroundColor(green);nav.setPadding(dp(2),dp(4),dp(2),dp(4));
  String[] ns={"DASHBOARD","CLIENTES","MOVIMENTO","HISTÓRICO","PDFS"};
  for(String n:ns){Button b=bt(n);b.setTextSize(9);b.setSingleLine(true);b.setMinWidth(0);b.setMinimumWidth(0);LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(0,dp(54),1);np.setMargins(dp(1),0,dp(1),0);nav.addView(b,np);if(n.equals("DASHBOARD"))b.setOnClickListener(v->dash());if(n.equals("CLIENTES"))b.setOnClickListener(v->clients());if(n.equals("MOVIMENTO"))b.setOnClickListener(v->movement());if(n.equals("HISTÓRICO"))b.setOnClickListener(v->history());if(n.equals("PDFS"))b.setOnClickListener(v->reports());}
  body.addView(nav,new LinearLayout.LayoutParams(-1,-2));Space gap=new Space(this);body.addView(gap,new LinearLayout.LayoutParams(1,dp(14)));sc.addView(body,new ScrollView.LayoutParams(-1,-2));setContentView(sc);
 }
 void dash(){shell("DASHBOARD");String[] t={"CLIENTES: "+db.countClients(),"COMPRARAM: "+db.count("VENDA"),"NÃO COMPRARAM: "+db.count("NÃO COMPROU"),"VISITADOS: "+db.count("VISITA"),"PEDIDOS: "+db.count("PEDIDO"),"ENTREGUES: "+db.count("PEDIDO ENTREGUE"),"TROCAS: "+db.count("TROCA"),"DEVOLUÇÕES: "+db.count("DEVOLUÇÃO"),"CANCELADOS: "+db.count("PEDIDO CANCELADO")};for(String x:t){TextView c=tv(x.toUpperCase(),18);c.setBackgroundColor(Color.WHITE);c.setPadding(dp(18),dp(18),dp(18),dp(18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(8));body.addView(c,lp);}Button pdf=bt("GERAR PDF DO DASHBOARD");body.addView(pdf,new LinearLayout.LayoutParams(-1,dp(58)));pdf.setOnClickListener(v->makePdf("DASHBOARD",new ArrayList<String>(Arrays.asList(t))));}
 void clients(){shell("CARTEIRA DE CLIENTES");Button novo=bt("+ NOVO CLIENTE");body.addView(novo,new LinearLayout.LayoutParams(-1,dp(58)));Button pc=bt("GERAR PDF DA CARTEIRA COMPLETA");body.addView(pc,new LinearLayout.LayoutParams(-1,dp(58)));pc.setOnClickListener(v->makePdf("CARTEIRA COMPLETA",db.report("CARTEIRA COMPLETA")));novo.setOnClickListener(v->editClient(0));for(String[] r:db.clients()){Button b=bt("✎  "+r[1].toUpperCase()+"\n"+r[2]+"  |  "+r[3]);body.addView(b);int id=Integer.parseInt(r[0]);b.setOnClickListener(v->editClient(id));}}
 void editClient(int id){String[] r=id==0?new String[]{"","",""}:db.client(id);LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(25,25,25,25);EditText n=new EditText(this);n.setHint("Nome / Razão Social");n.setText(r[0]);EditText d=new EditText(this);d.setHint("CPF / CNPJ");d.setText(r[1]);EditText p=new EditText(this);p.setHint("Telefone");p.setText(r[2]);l.addView(n);l.addView(d);l.addView(p);new AlertDialog.Builder(this).setTitle(id==0?"Novo cliente":"Editar cliente").setView(l).setPositiveButton("SALVAR",(x,w)->{if(id==0)db.addClient(n.getText().toString(),d.getText().toString(),p.getText().toString());else db.editClient(id,n.getText().toString(),d.getText().toString(),p.getText().toString());ArrayList<String> pdf=new ArrayList<>();pdf.add(n.getText().toString()+" | "+d.getText().toString()+" | "+p.getText().toString());makePdf(id==0?"NOVO CLIENTE":"CLIENTE EDITADO",pdf);clients();}).setNegativeButton("Cancelar",null).show();}
 void movement(){shell("REGISTRAR MOVIMENTAÇÃO");Spinner c=new Spinner(this);ArrayAdapter<String> ca=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.clientNames());c.setAdapter(ca);body.addView(c);Spinner tp=new Spinner(this);String[] types={"VENDA","NÃO COMPROU","VISITA","TROCA","DEVOLUÇÃO","PEDIDO","PEDIDO ENTREGUE","PEDIDO CANCELADO"};tp.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,types));body.addView(tp);EditText val=new EditText(this);val.setHint("Valor");body.addView(val);EditText obs=new EditText(this);obs.setHint("Observação");body.addView(obs);Button s=bt("SALVAR E GERAR PDF");body.addView(s);s.setOnClickListener(v->{int cid=db.clientIds().get(c.getSelectedItemPosition());db.addMove(cid,types[tp.getSelectedItemPosition()],val.getText().toString(),obs.getText().toString());makePdf("MOVIMENTO",db.lastMovementLines());Toast.makeText(this,"Movimento salvo e PDF gerado",0).show();dash();});}
 void history(){shell("HISTÓRICO");for(String x:db.history())body.addView(tv(x,15));Button p=bt("GERAR PDF DO HISTÓRICO");body.addView(p);p.setOnClickListener(v->makePdf("HISTORICO",db.history()));}
 void reports(){shell("RELATÓRIOS EM PDF");String[] rs={"RELATÓRIO DA SEMANA","QUEM COMPROU","QUEM NÃO COMPROU","VISITADOS","TROCAS","DEVOLUÇÕES","PEDIDOS","PEDIDOS ENTREGUES","PEDIDOS CANCELADOS","CARTEIRA COMPLETA"};for(String r:rs){Button b=bt(r+" - GERAR PDF");LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,dp(62));rp.setMargins(0,0,0,dp(8));body.addView(b,rp);b.setOnClickListener(v->makePdf(r,db.report(r)));}}
 void makePdf(String title,ArrayList<String> lines){try{PdfDocument doc=new PdfDocument();Paint p=new Paint();p.setColor(Color.BLACK);p.setTextSize(12);int pageNo=1,y=55;PdfDocument.Page page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,pageNo).create());Canvas c=page.getCanvas();p.setFakeBoldText(true);p.setTextSize(18);c.drawText("CASARÃO DO CAMPO - "+title,35,35,p);p.setFakeBoldText(false);p.setTextSize(11);for(String line:lines){if(y>805){doc.finishPage(page);pageNo++;page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,pageNo).create());c=page.getCanvas();y=45;}String z=line;while(z.length()>90){c.drawText(z.substring(0,90),35,y,p);y+=16;z=z.substring(90);}c.drawText(z,35,y,p);y+=18;}doc.finishPage(page);File dir=new File(getExternalFilesDir(null),"PDFs");dir.mkdirs();File f=new File(dir,title.replace(" ","_")+"_"+new SimpleDateFormat("yyyyMMdd_HHmmss").format(new Date())+".pdf");FileOutputStream o=new FileOutputStream(f);doc.writeTo(o);o.close();doc.close();new AlertDialog.Builder(this).setTitle("PDF GERADO").setMessage(f.getAbsolutePath()).setPositiveButton("OK",null).show();}catch(Exception e){new AlertDialog.Builder(this).setTitle("Erro PDF").setMessage(e.toString()).show();}}
}

class DB extends SQLiteOpenHelper{
 Context ctx; DB(Context c){super(c,"carteira.db",null,3);ctx=c;}public void onCreate(SQLiteDatabase d){d.execSQL("create table clientes(id integer primary key autoincrement,nome text,doc text,tel text)");d.execSQL("create table mov(id integer primary key autoincrement,cid integer,data text,tipo text,valor real,obs text)");importar258(d);}public void onUpgrade(SQLiteDatabase d,int a,int b){/* V4 preserva clientes e movimentações existentes */}void importar258(SQLiteDatabase d){try{BufferedReader br=new BufferedReader(new InputStreamReader(ctx.getAssets().open("clientes_258.csv"),"UTF-8"));String line;boolean first=true;while((line=br.readLine())!=null){if(first){first=false;continue;}ArrayList<String> f=parseCsv(line);while(f.size()<4)f.add("");d.execSQL("insert into clientes(nome,doc,tel) values(?,?,?)",new Object[]{f.get(1),f.get(2),f.get(3)});}br.close();}catch(Exception e){d.execSQL("insert into clientes(nome,doc,tel) values('ERRO AO CARREGAR CARTEIRA','','')");}}ArrayList<String> parseCsv(String line){ArrayList<String>a=new ArrayList<>();StringBuilder z=new StringBuilder();boolean q=false;for(int i=0;i<line.length();i++){char c=line.charAt(i);if(c=='"'){if(q&&i+1<line.length()&&line.charAt(i+1)=='"'){z.append('"');i++;}else q=!q;}else if(c==','&&!q){a.add(z.toString());z.setLength(0);}else z.append(c);}a.add(z.toString());return a;}
 int countClients(){Cursor c=getReadableDatabase().rawQuery("select count(*) from clientes",null);c.moveToFirst();return c.getInt(0);}int count(String t){Cursor c=getReadableDatabase().rawQuery("select count(*) from mov where tipo=?",new String[]{t});c.moveToFirst();return c.getInt(0);}ArrayList<String[]> clients(){ArrayList<String[]> a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("select id,nome,doc,tel from clientes order by nome",null);while(c.moveToNext())a.add(new String[]{c.getString(0),c.getString(1),c.getString(2),c.getString(3)});return a;}String[] client(int id){Cursor c=getReadableDatabase().rawQuery("select nome,doc,tel from clientes where id=?",new String[]{""+id});c.moveToFirst();return new String[]{c.getString(0),c.getString(1),c.getString(2)};}void addClient(String n,String d,String t){getWritableDatabase().execSQL("insert into clientes(nome,doc,tel) values(?,?,?)",new Object[]{n,d,t});}void editClient(int id,String n,String d,String t){getWritableDatabase().execSQL("update clientes set nome=?,doc=?,tel=? where id=?",new Object[]{n,d,t,id});}ArrayList<String> clientNames(){ArrayList<String>a=new ArrayList<>();for(String[]r:clients())a.add(r[1]);return a;}ArrayList<Integer> clientIds(){ArrayList<Integer>a=new ArrayList<>();for(String[]r:clients())a.add(Integer.parseInt(r[0]));return a;}void addMove(int cid,String tipo,String val,String obs){double v=0;try{v=Double.parseDouble(val.replace(".","").replace(",","."));}catch(Exception e){}getWritableDatabase().execSQL("insert into mov(cid,data,tipo,valor,obs) values(?,?,?,?,?)",new Object[]{cid,new SimpleDateFormat("dd/MM/yyyy HH:mm").format(new Date()),tipo,v,obs});}ArrayList<String> history(){ArrayList<String>a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("select m.data,c.nome,m.tipo,m.valor,m.obs from mov m join clientes c on c.id=m.cid order by m.id desc",null);while(c.moveToNext())a.add(c.getString(0)+" | "+c.getString(1)+" | "+c.getString(2)+" | R$ "+String.format("%.2f",c.getDouble(3))+" | "+c.getString(4));return a;}ArrayList<String> lastMovementLines(){ArrayList<String>a=new ArrayList<>();Cursor c=getReadableDatabase().rawQuery("select m.data,c.nome,c.doc,c.tel,m.tipo,m.valor,m.obs from mov m join clientes c on c.id=m.cid order by m.id desc limit 1",null);if(c.moveToFirst())a.add(c.getString(0)+" | "+c.getString(1)+" | "+c.getString(2)+" | "+c.getString(3)+" | "+c.getString(4)+" | R$ "+c.getDouble(5)+" | "+c.getString(6));return a;}ArrayList<String> report(String r){if(r.equals("CARTEIRA COMPLETA")){ArrayList<String>a=new ArrayList<>();for(String[]x:clients())a.add(x[1]+" | "+x[2]+" | "+x[3]);return a;}String tipo=null;if(r.equals("QUEM COMPROU"))tipo="VENDA";if(r.equals("QUEM NÃO COMPROU"))tipo="NÃO COMPROU";if(r.equals("VISITADOS"))tipo="VISITA";if(r.equals("TROCAS"))tipo="TROCA";if(r.equals("DEVOLUÇÕES"))tipo="DEVOLUÇÃO";if(r.equals("PEDIDOS"))tipo="PEDIDO";if(r.equals("PEDIDOS ENTREGUES"))tipo="PEDIDO ENTREGUE";if(r.equals("PEDIDOS CANCELADOS"))tipo="PEDIDO CANCELADO";ArrayList<String>a=new ArrayList<>();String sql="select m.data,c.nome,c.doc,c.tel,m.tipo,m.valor,m.obs from mov m join clientes c on c.id=m.cid";ArrayList<String> args=new ArrayList<>();if(tipo!=null){sql+=" where m.tipo=?";args.add(tipo);}sql+=" order by m.id desc";Cursor c=getReadableDatabase().rawQuery(sql,args.toArray(new String[0]));while(c.moveToNext())a.add(c.getString(0)+" | "+c.getString(1)+" | "+c.getString(2)+" | "+c.getString(3)+" | "+c.getString(4)+" | R$ "+c.getDouble(5)+" | "+c.getString(6));return a;}}
